def main(data: str = "", query: str = "") -> dict:
    import json

    chapter_names = ("活动概况与重点关注", "日进站量 / 出站量", "日进站量与出站量", "日最大断面量", "全日分时最大断面量", "日换乘量", "日OD量", "活动概况", "车站客流", "线路断面", "分时断面", "换乘客流", "OD", "overview", "station", "section", "hourly", "transfer", "od", "第零章_活动概况与重点关注", "第一章_日进站量与出站量", "第二章_日最大断面量", "第三章_全日分时最大断面", "第四章_日换乘量", "第五章_日起讫点客流量", "0_活动概况与重点关注", "1_日进站量与出站量", "2_日最大断面量", "3_全日分时最大断面量", "4_日换乘量", "5_日OD量", "5_日起讫点客流量")

    def extract_object(raw):
        if isinstance(raw, dict):
            return raw
        if not isinstance(raw, str) or not raw.strip():
            raise ValueError("输入为空或不是JSON对象/字符串")
        text = raw.strip()
        # 按码点移除开头的BOM，避免编辑器把不可见字符显示为乱码。
        while text and ord(text[0]) == 0xFEFF:
            text = text[1:].strip()
        if text.startswith("```"):
            lines = text.splitlines()
            lines = lines[1:]
            if lines and lines[-1].strip() == "```":
                lines = lines[:-1]
            text = "\n".join(lines).strip()
        try:
            value = json.loads(text)
        except (TypeError, ValueError):
            # 兼容既有调用方在JSON前后附带说明文字的情况。
            start = text.find("{")
            if start < 0:
                raise ValueError("未找到JSON对象")
            value, _ = json.JSONDecoder().raw_decode(text[start:])
        # 部分平台会再序列化一层JSON字符串，限制层数避免无限解包。
        for _ in range(3):
            if not isinstance(value, str):
                break
            value = json.loads(value)
        if not isinstance(value, dict):
            raise ValueError("JSON根节点必须是Object")
        return value

    def unwrap(value):
        for _ in range(5):
            if any(name in value for name in chapter_names):
                return value
            inputs = value.get("inputs")
            if isinstance(inputs, dict) and "data" in inputs:
                value = extract_object(inputs["data"])
            elif "data" in value and isinstance(value["data"], (dict, str)):
                value = extract_object(value["data"])
            else:
                return value
        raise ValueError("请求报文嵌套超过5层")

    errors = []
    for label, raw in (("data", data), ("query", query)):
        try:
            value = unwrap(extract_object(raw))
            return {"parsed_data": value, "parse_ok": True, "parse_err": ""}
        except Exception as exc:
            errors.append(f"{label}：{exc}")
    return {"parsed_data": {}, "parse_ok": False, "parse_err": "；".join(errors)}

def main(report_title: str, content_活动概况与重点关注: str, content_日进站量与出站量: str, content_日最大断面量: str, content_全日分时最大断面量: str, content_日换乘量: str, content_日OD量: str, packet_活动概况与重点关注: str, packet_日进站量与出站量: str, packet_日最大断面量: str, packet_全日分时最大断面量: str, packet_日换乘量: str, packet_日OD量: str) -> dict:
    import json
    import re

    CHAPTERS = ("活动概况与重点关注", "日进站量/出站量", "日最大断面量", "全日分时最大断面量", "日换乘量", "日OD量")

    def numeric_tokens(value):
        text = str(value or "")
        result = set()
        for token in re.findall(r"(?<![A-Za-z0-9])\d+(?:\.\d+)?", text.replace(",", "")):
            number = float(token)
            result.add(str(int(number)) if number.is_integer() else format(number, ".12g"))
        return result

    def normalize(text, heading, source_packet):
        if not isinstance(text, str) or not text.strip():
            raise ValueError(f"{heading}模型输出为空")
        value = text.strip()
        # 按码点移除开头的BOM，避免编辑器把不可见字符显示为乱码。
        while value and ord(value[0]) == 0xFEFF:
            value = value[1:].strip()
        if value.startswith("```") or value.startswith("{") or value.startswith("["):
            raise ValueError(f"{heading}必须直接输出Markdown正文")
        lines = value.splitlines()
        if lines and re.match(r"^#{1,6}\s+", lines[0].strip()):
            value = "\n".join(lines[1:]).strip()
        if not value:
            raise ValueError(f"{heading}模型输出只有标题、没有正文")
        if len(value) > 1500:
            raise ValueError(f"{heading}输出超过1500字符")
        if re.search(r"(?m)^#{1,6}\s+", value):
            raise ValueError(f"{heading}正文不得包含Markdown标题")
        unknown = sorted(numeric_tokens(value) - numeric_tokens(source_packet), key=lambda item: float(item))
        if unknown:
            # 字面匹配不能确认近似表述、单位换算或推导值的语义，只作核对提示。
            print(
                f"[WARN] {heading}数字未在本章输入中原样匹配：{unknown[:8]}；"
                "仅提示核对，未确认数值正确，不中断报告生成。"
            )
        return value.strip()


    def chapter_result(chapter_id, content, packet):
        if chapter_id not in CHAPTERS:
            raise ValueError("输出章节ID不符合固定契约")
        source = json.loads(packet)
        if source.get("chapter_id") != chapter_id:
            raise ValueError("模型正文对应的任务包章节不一致")
        return normalize(content, chapter_id, packet)

    rows = [
        ("活动概况与重点关注", content_活动概况与重点关注, packet_活动概况与重点关注),
        ("日进站量/出站量", content_日进站量与出站量, packet_日进站量与出站量),
        ("日最大断面量", content_日最大断面量, packet_日最大断面量),
        ("全日分时最大断面量", content_全日分时最大断面量, packet_全日分时最大断面量),
        ("日换乘量", content_日换乘量, packet_日换乘量),
        ("日OD量", content_日OD量, packet_日OD量),
    ]
    chapters = {key: chapter_result(key, content, packet) for key, content, packet in rows}
    parts = [f"# {report_title.strip()}"]
    for key, content in chapters.items():
        parts.extend([f"## {key}", content])
    return {"md_text": "\n\n".join(parts) + "\n", "md_chapter_json": chapters}
